package node

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"

	"topsailai_connector/internal/security"
)

// CredentialFileName is the file inside the config directory that holds the
// credentials this Node accepts from callers.
//
// The credentials live in a file rather than in the identity file because the two
// answer different questions. The identity file names the Node and is generated by
// the Node itself; the credential file lists who may operate on it and is written
// by the operator. Merging them would make "regenerate my identity" and "revoke a
// caller" the same command, and a regeneration would silently revoke every caller.
const CredentialFileName = "credentials.yaml"

// credentialFileMode is the mode the credential file is created with. It holds
// HMAC secrets that never expire, so it is readable by its owner and nobody else.
const credentialFileMode = 0o600

// ErrCredentialsMissing reports that no credential file exists yet.
//
// It is a distinct error because the caller's response is different: a missing file
// is generated with one credential so a fresh Node is reachable, while a malformed
// file is a startup failure. Generating over a malformed file would silently
// invalidate every credential the operator had already copied into a CLI.
var ErrCredentialsMissing = errors.New("node credential file is missing")

// CredentialsPath returns the credential file path inside a config directory.
func CredentialsPath(configDir string) string {
	return filepath.Join(configDir, CredentialFileName)
}

// LoadCredentials reads the credential file at path.
//
// Every failure is a refusal rather than a repair. The file is parsed by the same
// strict decoder the Server uses, so a Node and a Server cannot disagree about what
// a valid credential file is: an unknown key, a missing version, a duplicate key
// identifier and an oversized file are refused on both sides.
func LoadCredentials(path string) (*security.CredentialSet, error) {
	content, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("%w: %s", ErrCredentialsMissing, path)
		}
		return nil, fmt.Errorf("read credential file %q: %w", path, err)
	}

	if err := checkCredentialFileMode(path); err != nil {
		return nil, err
	}

	credentials, err := security.ParseCredentialSet(content)
	if err != nil {
		return nil, fmt.Errorf("credential file %q: %w", path, err)
	}
	return credentials, nil
}

// checkCredentialFileMode refuses a credential file that another user can read.
//
// The check is skipped on Windows, where the permission bits Go reports are
// synthesised from the read-only attribute and carry no ownership information. A
// check that cannot answer the question must not pretend to: it would refuse every
// file on one platform and accept every file on the other.
func checkCredentialFileMode(path string) error {
	if runtime.GOOS == "windows" {
		return nil
	}
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("stat credential file %q: %w", path, err)
	}
	if mode := info.Mode().Perm(); mode&0o077 != 0 {
		return fmt.Errorf("credential file %q has mode %04o, want no group or other access; it holds secrets that never expire", path, mode)
	}
	return nil
}

// SaveCredentials writes a credential set to path with owner-only permissions.
//
// The write is atomic: the content goes to a temporary file in the same directory
// and is renamed over the target. A partial write would leave a file that parses as
// neither the old set nor the new one, and the operator would have no way to tell
// which credentials the Node now accepts.
//
// The temporary file is removed on every failure path, so a failed save does not
// leave a stray file holding a secret.
func SaveCredentials(path string, credentials []security.Credential) error {
	content, err := security.FormatCredentialSet(credentials)
	if err != nil {
		return err
	}

	directory := filepath.Dir(path)
	temporary, err := os.CreateTemp(directory, ".credentials-*")
	if err != nil {
		return fmt.Errorf("create temporary credential file in %q: %w", directory, err)
	}
	temporaryPath := temporary.Name()

	cleanup := func() {
		temporary.Close()
		if err := os.Remove(temporaryPath); err != nil && !errors.Is(err, os.ErrNotExist) {
			// A stray temporary file holds a secret, so a failure to remove it is
			// reported rather than swallowed.
			fmt.Fprintf(os.Stderr, "remove temporary credential file %q: %v\n", temporaryPath, err)
		}
	}

	if err := temporary.Chmod(credentialFileMode); err != nil {
		cleanup()
		return fmt.Errorf("set mode on temporary credential file %q: %w", temporaryPath, err)
	}
	if _, err := temporary.Write(content); err != nil {
		cleanup()
		return fmt.Errorf("write temporary credential file %q: %w", temporaryPath, err)
	}
	if err := temporary.Sync(); err != nil {
		cleanup()
		return fmt.Errorf("sync temporary credential file %q: %w", temporaryPath, err)
	}
	if err := temporary.Close(); err != nil {
		cleanup()
		return fmt.Errorf("close temporary credential file %q: %w", temporaryPath, err)
	}
	if err := os.Rename(temporaryPath, path); err != nil {
		cleanup()
		return fmt.Errorf("rename temporary credential file over %q: %w", path, err)
	}
	return nil
}

// EnsureCredentials loads the credential file, generating one credential when the
// file does not exist yet.
//
// The generated credential is returned separately so the caller can print it once.
// A Node that started with no credential would accept nothing, which looks exactly
// like a Node whose policy denies everything; generating one makes a fresh Node
// reachable and makes the value the operator must copy explicit.
//
// The credential is returned only when it was created by this call. Printing it on
// every start would put a secret into a log on every start, which is the leak the
// design forbids.
func EnsureCredentials(path string) (set *security.CredentialSet, generated *security.Credential, err error) {
	return EnsureCredentialsWithSeed(path, security.Credential{})
}

// EnsureCredentialsWithSeed loads the credential file, writing seed when the file
// does not exist yet and generating a random credential when seed is empty.
//
// The file wins over the seed, for the same reason the identity file does: a Node
// that preferred the seed would undo `credential remove`, so a revoked caller would
// work again after a restart. The seed only decides what the first write contains.
//
// A seed that fails validation is an error rather than a fallback to a random
// credential. A packaging mistake that silently produced a different secret would
// hand the operator a value that does not authenticate, and the failure would appear
// on the recipient's machine rather than at packaging time.
func EnsureCredentialsWithSeed(path string, seed security.Credential) (set *security.CredentialSet, generated *security.Credential, err error) {
	loaded, err := LoadCredentials(path)
	if err == nil {
		return loaded, nil, nil
	}
	if !errors.Is(err, ErrCredentialsMissing) {
		return nil, nil, err
	}

	created := seed
	if created.KeyID == "" {
		created, err = security.NewCredential()
		if err != nil {
			return nil, nil, err
		}
	}
	if err := SaveCredentials(path, []security.Credential{created}); err != nil {
		return nil, nil, err
	}
	createdSet, err := security.NewCredentialSet([]security.Credential{created})
	if err != nil {
		return nil, nil, err
	}
	return createdSet, &created, nil
}
